"use client";
import { useWorkspaceEntitlements } from "@/components/workspace-quota";
import Link from "next/link";
export function UpgradePrompt({
  children,
  planLabel = "Paid",
}: {
  children?: React.ReactNode;
  planLabel?: "Paid" | "Premium";
}) {
  const access = useWorkspaceEntitlements();
  if (access.reasons.send === "ACCOUNT_SUSPENDED")
    return (
      <p className="text-sm text-body">
        Account access is suspended.{" "}
        <Link href="/usage" className="text-link underline">
          Manage subscription
        </Link>{" "}
        or contact support.
      </p>
    );
  return (
    <p className="text-sm leading-6 text-body">
      {children}{" "}
      <Link
        className="inline-flex min-h-11 items-center text-link underline"
        href="/usage"
      >
        View {planLabel} plan
      </Link>{" "}
      · Checkout is available in Usage when configured.
    </p>
  );
}
